function biggestTriple(digits: string): string {
  let best = -1;
  for (let i = 0; i + 2 < digits.length; i++) {
    if (digits[i] === digits[i + 1] && digits[i] === digits[i + 2]) {
      best = Math.max(best, Number(digits[i]));
    }
  }
  return best < 0 ? "" : String(best).repeat(3);
}

