    def biggestTriple(self, digits: str) -> str:
        best = -1
        for i in range(len(digits) - 2):
            if digits[i] == digits[i + 1] == digits[i + 2]:
                best = max(best, int(digits[i]))
        return "" if best < 0 else str(best) * 3

